from typing import List

def find_number_of_perfect_pairs(nums: List[int]) -> int:
    a = sorted(abs(x) for x in nums)
    n, j, count = len(a), 0, 0
    for i in range(n):
        j = max(j, i + 1)
        while j < n and a[j] <= 2 * a[i]:
            j += 1
        count += j - i - 1   # a[i+1..j-1] 都能和 a[i] 配对
    return count

if __name__ == "__main__":
    assert find_number_of_perfect_pairs([2, -3, 5]) == 2
    print("ok")
